// Regression tests for findings F5 and R2-F5 (seeder upstream TLS
// verification and bounded negotiation).
//   node --test infra/learner-lab/ops/verified-postgres-forwarder.test.mjs
// STOCKWISE_FORWARDER_MODULE=<path> runs the same tests against another copy
// of the module (used to reproduce findings on the pre-remediation source).
// A fake PostgreSQL server answers SSLRequest and upgrades to TLS with test
// certificates generated by the local openssl CLI in a temporary directory.
import assert from "node:assert/strict";
import { Buffer } from "node:buffer";
import { execFileSync } from "node:child_process";
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { createRequire } from "node:module";
import { connect as tcpConnect, createServer } from "node:net";
import { tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";
import process from "node:process";
import { clearTimeout, setTimeout } from "node:timers";
import { after, before, test } from "node:test";
import { TLSSocket } from "node:tls";
import { URL, fileURLToPath, pathToFileURL } from "node:url";

const {
  assertVerifiedTlsSettings,
  createVerifiedPostgresForwarder,
  verifiedUpstream,
} = await import(
  process.env.STOCKWISE_FORWARDER_MODULE
    ? pathToFileURL(resolve(process.env.STOCKWISE_FORWARDER_MODULE)).href
    : "./verified-postgres-forwarder.mjs"
);

const here = dirname(fileURLToPath(import.meta.url));
const directory = mkdtempSync(join(tmpdir(), "stockwise-f5-"));
const file = (name) => join(directory, name);
const openssl = (...args) =>
  execFileSync("openssl", args, { cwd: directory, stdio: "pipe" });
let pem;

before(() => {
  for (const ca of ["trusted-ca", "untrusted-ca"]) {
    openssl(
      "req",
      "-x509",
      "-newkey",
      "rsa:2048",
      "-nodes",
      "-days",
      "2",
      "-subj",
      `/CN=${ca}`,
      "-keyout",
      `${ca}.key`,
      "-out",
      `${ca}.pem`,
    );
  }
  const issue = (name, ca, extra = []) => {
    openssl(
      "req",
      "-newkey",
      "rsa:2048",
      "-nodes",
      "-subj",
      "/CN=db.test",
      "-keyout",
      `${name}.key`,
      "-out",
      `${name}.csr`,
    );
    writeFileSync(file(`${name}.ext`), "subjectAltName=DNS:db.test\n");
    openssl(
      "x509",
      "-req",
      "-in",
      `${name}.csr`,
      "-CA",
      `${ca}.pem`,
      "-CAkey",
      `${ca}.key`,
      "-CAcreateserial",
      "-extfile",
      `${name}.ext`,
      "-out",
      `${name}.pem`,
      ...extra,
    );
  };
  issue("server", "trusted-ca", ["-days", "2"]);
  issue("server-untrusted", "untrusted-ca", ["-days", "2"]);
  issue("server-expired", "trusted-ca", [
    "-not_before",
    "20200101000000Z",
    "-not_after",
    "20200102000000Z",
  ]);
  pem = (name) => readFileSync(file(name));
});
after(() => rmSync(directory, { recursive: true, force: true }));

// Fake PostgreSQL: SSLRequest -> 'S' (or 'N') -> TLS -> answers PING with PONG.
async function fakePostgres({ certificate, refuseTls = false }) {
  const sessions = [];
  const server = createServer((socket) => {
    socket.once("data", (request) => {
      if (refuseTls) {
        socket.end("N");
        return;
      }
      assert.equal(request.toString("hex"), "0000000804d2162f");
      socket.write("S");
      const secure = new TLSSocket(socket, {
        isServer: true,
        key: pem(`${certificate}.key`),
        cert: pem(`${certificate}.pem`),
      });
      secure.on("secure", () => sessions.push("tls"));
      secure.on("error", () => {});
      secure.on("data", (data) => {
        if (data.toString() === "PING") secure.write("PONG");
      });
    });
    socket.on("error", () => {});
  });
  await new Promise((ready) => server.listen(0, "127.0.0.1", ready));
  return {
    port: server.address().port,
    sessions,
    close: () => new Promise((done) => server.close(done)),
  };
}

// Connects through the forwarder, sends PING and resolves the reply ("" when closed).
async function roundTrip({
  certificate,
  servername = "db.test",
  ca = "trusted-ca.pem",
  refuseTls = false,
}) {
  const upstream = await fakePostgres({ certificate, refuseTls });
  const rejections = [];
  const forwarder = await createVerifiedPostgresForwarder({
    upstreamHost: "127.0.0.1",
    upstreamPort: upstream.port,
    servername,
    ca: pem(ca),
    onRejected: (error) => rejections.push(error.message),
  });
  const reply = await new Promise((resolve) => {
    const client = tcpConnect(forwarder.port, "127.0.0.1", () =>
      client.write("PING"),
    );
    let received = "";
    client.on("data", (data) => {
      received += data;
      client.end();
    });
    client.on("close", () => resolve(received));
    client.on("error", () => resolve(received));
  });
  await forwarder.close();
  await upstream.close();
  return { reply, rejections };
}

test("correct CA and RDS hostname: forwarded over verified TLS", async () => {
  const { reply, rejections } = await roundTrip({ certificate: "server" });
  assert.equal(reply, "PONG");
  assert.deepEqual(rejections, []);
});

test("certificate from an untrusted CA is rejected before any byte is forwarded", async () => {
  const { reply, rejections } = await roundTrip({
    certificate: "server-untrusted",
  });
  assert.equal(reply, "");
  assert.match(
    rejections[0],
    /^UPSTREAM_TLS_REJECTED:(UNABLE_TO_VERIFY_LEAF_SIGNATURE|SELF_SIGNED_CERT_IN_CHAIN|UNABLE_TO_GET_ISSUER_CERT_LOCALLY)/,
  );
});

test("hostname mismatch is rejected", async () => {
  const { reply, rejections } = await roundTrip({
    certificate: "server",
    servername: "other-rds.test",
  });
  assert.equal(reply, "");
  assert.match(
    rejections[0],
    /^UPSTREAM_TLS_REJECTED:ERR_TLS_CERT_ALTNAME_INVALID/,
  );
});

test("expired certificate is rejected", async () => {
  const { reply, rejections } = await roundTrip({
    certificate: "server-expired",
  });
  assert.equal(reply, "");
  assert.match(rejections[0], /^UPSTREAM_TLS_REJECTED:CERT_HAS_EXPIRED/);
});

test("a server that refuses TLS is rejected (no plaintext fallback)", async () => {
  const { reply, rejections } = await roundTrip({
    certificate: "server",
    refuseTls: true,
  });
  assert.equal(reply, "");
  assert.deepEqual(rejections, ["UPSTREAM_REFUSED_TLS"]);
});

test("explicit no-verify or downgraded settings fail closed", () => {
  const verified = new URL(
    "postgresql://u:p@db.test:5432/x_demo?sslmode=verify-full",
  );
  assert.doesNotThrow(() => assertVerifiedTlsSettings(verified, {}));
  assert.doesNotThrow(() =>
    assertVerifiedTlsSettings(verified, { PGSSLMODE: "verify-full" }),
  );
  assert.throws(
    () => assertVerifiedTlsSettings(verified, { PGSSLMODE: "no-verify" }),
    /SEED_PGSSLMODE_MUST_BE_VERIFY_FULL/,
  );
  assert.throws(
    () => assertVerifiedTlsSettings(verified, { PGSSLMODE: "require" }),
    /SEED_PGSSLMODE_MUST_BE_VERIFY_FULL/,
  );
  assert.throws(
    () =>
      assertVerifiedTlsSettings(verified, {
        STOCKWISE_SEED_PGSSLMODE: "no-verify",
      }),
    /SEED_TLS_OVERRIDE_REFUSED/,
  );
  assert.throws(
    () =>
      assertVerifiedTlsSettings(verified, {
        NODE_TLS_REJECT_UNAUTHORIZED: "0",
      }),
    /SEED_TLS_VERIFICATION_DISABLED/,
  );
  const noVerify = new URL(
    "postgresql://u:p@db.test:5432/x_demo?sslmode=no-verify",
  );
  assert.throws(
    () => assertVerifiedTlsSettings(noVerify, {}),
    /SEED_SOURCE_MUST_BE_VERIFY_FULL/,
  );
});

test("REPRODUCTION of F5: node-postgres with the former PGSSLMODE=no-verify completes TLS to an untrusted server", async () => {
  const require = createRequire(join(here, "../../../apps/api/package.json"));
  const { Client } = require("pg");
  const upstream = await fakePostgres({ certificate: "server-untrusted" });
  const client = new Client({
    host: "127.0.0.1",
    port: upstream.port,
    user: "u",
    database: "x_demo",
    ssl: { rejectUnauthorized: false }, // what PGSSLMODE=no-verify selects in node-postgres
    connectionTimeoutMillis: 1500,
  });
  await client.connect().catch(() => {});
  await client.end().catch(() => {});
  await upstream.close();
  assert.deepEqual(
    upstream.sessions,
    ["tls"],
    "the untrusted certificate was accepted by the former setting",
  );
});

// ---- R2-F5: negotiation always settles, within its bound, without leaks ------

// A raw upstream that misbehaves before or during negotiation. Tracks open
// server-side sockets so a leaked connection is visible.
async function misbehavingUpstream(behaviour) {
  const open = new Set();
  const server = createServer((socket) => {
    open.add(socket);
    socket.on("close", () => open.delete(socket));
    socket.on("error", () => {});
    socket.once("data", () => {
      if (behaviour === "eof") socket.end();
      else if (behaviour === "close") socket.destroy();
      else if (behaviour === "extra-bytes")
        socket.write(Buffer.from("SXtrailing-plaintext"));
      else if (behaviour === "malformed") socket.write("X");
      else if (behaviour === "accept-then-eof") socket.end("S");
      // "silent": never answers.
    });
  });
  await new Promise((ready) => server.listen(0, "127.0.0.1", ready));
  return {
    port: server.address().port,
    open,
    close: () =>
      new Promise((done) => {
        for (const socket of open) socket.destroy();
        server.close(() => done());
      }),
  };
}

// Settles verifiedUpstream() or fails the test after boundMs (a hang).
async function settleWithin(promise, boundMs) {
  let timer;
  const hang = new Promise((_, reject) => {
    timer = setTimeout(
      () => reject(new Error(`NOT_SETTLED_WITHIN_${boundMs}MS`)),
      boundMs,
    );
  });
  try {
    return await Promise.race([
      promise.then(
        (value) => ({ value }),
        (error) => ({ error }),
      ),
      hang,
    ]);
  } finally {
    clearTimeout(timer);
  }
}

const waitFor = async (predicate, ms = 1000) => {
  const start = Date.now();
  while (!predicate() && Date.now() - start < ms)
    await new Promise((done) => setTimeout(done, 10));
  return predicate();
};

for (const [behaviour, expected] of [
  ["eof", /^UPSTREAM_CLOSED_BEFORE_TLS$/],
  ["close", /^UPSTREAM_CLOSED_BEFORE_TLS$/],
  ["extra-bytes", /^UPSTREAM_SENT_DATA_BEFORE_TLS$/],
  ["malformed", /^UPSTREAM_MALFORMED_SSL_REPLY$/],
  [
    "accept-then-eof",
    /^UPSTREAM_(CLOSED_DURING_TLS|CLOSED_BEFORE_TLS|TLS_REJECTED:.*)$/,
  ],
  ["silent", /^UPSTREAM_TIMEOUT$/],
]) {
  test(`upstream ${behaviour} settles once, within the bound, and leaves no connection`, async () => {
    const upstream = await misbehavingUpstream(behaviour);
    const outcome = await settleWithin(
      verifiedUpstream({
        host: "127.0.0.1",
        port: upstream.port,
        servername: "db.test",
        ca: pem("trusted-ca.pem"),
        timeoutMs: 400,
      }),
      2000,
    );
    assert.ok(
      outcome.error,
      `expected a rejection, got ${outcome.value ? "a connection" : "nothing"}`,
    );
    assert.match(outcome.error.message, expected);
    assert.ok(
      await waitFor(() => upstream.open.size === 0),
      "the upstream connection was not closed",
    );
    await upstream.close();
  });
}

test("connection refused settles as an error within the bound", async () => {
  const unused = await misbehavingUpstream("silent");
  const port = unused.port;
  await unused.close();
  const outcome = await settleWithin(
    verifiedUpstream({
      host: "127.0.0.1",
      port,
      servername: "db.test",
      ca: pem("trusted-ca.pem"),
      timeoutMs: 400,
    }),
    2000,
  );
  assert.match(
    outcome.error?.message ?? "",
    /^UPSTREAM_(CONNECT_FAILED:ECONNREFUSED|CLOSED_BEFORE_TLS)$/,
  );
});

test("the valid TLS path resolves once, before the deadline, and the deadline never fires afterwards", async () => {
  const upstream = await fakePostgres({ certificate: "server" });
  const outcome = await settleWithin(
    verifiedUpstream({
      host: "127.0.0.1",
      port: upstream.port,
      servername: "db.test",
      ca: pem("trusted-ca.pem"),
      timeoutMs: 300,
    }),
    2000,
  );
  assert.ok(outcome.value?.authorized, "verified TLS session expected");
  // Outlive the deadline: a stray timer would destroy the live session.
  await new Promise((done) => setTimeout(done, 450));
  assert.equal(outcome.value.destroyed, false);
  outcome.value.destroy();
  await upstream.close();
});

test("a client that leaves the forwarder during an early-EOF upstream leaves nothing open", async () => {
  const upstream = await misbehavingUpstream("eof");
  const rejections = [];
  const forwarder = await createVerifiedPostgresForwarder({
    upstreamHost: "127.0.0.1",
    upstreamPort: upstream.port,
    servername: "db.test",
    ca: pem("trusted-ca.pem"),
    timeoutMs: 400,
    onRejected: (error) => rejections.push(error.message),
  });
  const closed = await settleWithin(
    new Promise((done) => {
      const client = tcpConnect(forwarder.port, "127.0.0.1", () =>
        client.write("PING"),
      );
      client.on("close", () => done("closed"));
      client.on("error", () => {});
    }),
    2000,
  );
  assert.equal(closed.value, "closed");
  assert.deepEqual(rejections, ["UPSTREAM_CLOSED_BEFORE_TLS"]);
  assert.ok(await waitFor(() => upstream.open.size === 0));
  await forwarder.close();
  await upstream.close();
});
